thor-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"836a38b3-271d-51e7-b452-17062cee67d4","unit_id":"5d4e5499-ce40-5871-833f-a03416dc68f1","title":"Уступка без потери позиции","position":5,"description":"Строим аргумент, который признаёт ограничение, но сохраняет основную обоснованную позицию.","level":"C1","objectives":["Различать уступку, условие и контраст","Использовать even if, whereas и nonetheless"],"notes":["Even if вводит условие, которое не меняет главный вывод; оно не подтверждает, что условие выполнено.","Whereas сопоставляет разные положения дел; nonetheless сохраняет вывод вопреки названному ограничению."],"lexicon":[{"en":"nonetheless","ru":"тем не менее"},{"en":"whereas","ru":"тогда как"},{"en":"concede","ru":"признавать довод или уступать"},{"en":"feasibility","ru":"осуществимость"}],"skills":["vocabulary","reading","grammar"],"estimated_minutes":12,"prerequisites":["d7d86ac8-bfd7-5760-979f-dd08aa72b0de"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"91628438-0914-524a-ae2c-77665a7f5aa6","unit_id":"e713b82c-3ff1-53a3-b533-9fc65a76a757","title":"Похвала, ирония и недосказанность","position":1,"description":"Различаем буквальную похвалу, ироническую оценку и ограниченный вывод из контекста.","level":"C2","objectives":["Интерпретировать ироническую похвалу по контексту","Сохранять сдержанную критику в переводе"],"notes":["Ироническая оценка определяется контекстом, а не самим наличием положительного прилагательного.","An ambitious interpretation может вежливо намекать на чрезмерность вывода, но не всегда является насмешкой."],"lexicon":[{"en":"understatement","ru":"сдержанное преуменьшение"},{"en":"ironic","ru":"иронический"},{"en":"qualified praise","ru":"похвала с оговорками"},{"en":"overstatement","ru":"преувеличение"}],"skills":["reading","vocabulary","grammar"],"