r","ru":"стул"},{"en":"child","ru":"ребёнок"},{"en":"children","ru":"дети"},{"en":"shelf","ru":"полка"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"a2efeeaf-ef59-53bc-a749-26544cb77165","unit_id":"b331cad6-c533-514a-a26c-d50381891cb0","title":"Простые вежливые просьбы","position":14,"description":"Просим открыть окно, передать предмет или повторить фразу и реагируем на просьбу.","level":"A1","objectives":["Построить Can you …, please?","Согласиться выполнить просьбу"],"notes":["Can you open …? может быть просьбой, а не проверкой способности.","Please делает просьбу вежливее; после can глагол без to."],"lexicon":[{"en":"pass","ru":"передавать"},{"en":"repeat","ru":"повторять"},{"en":"window","ru":"окно"},{"en":"certainly","ru":"конечно"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"9b4ccf96-8296-5c13-ae84-7743f47ae4db","unit_id":"b331cad6-c533-514a-a26c-d50381891cb0","title":"Цена и оплата","position":15,"description":"Спрашиваем цену товара и понимаем простую сумму и способ оплаты.","level":"A1","objectives":["Спросить цену с How much","Попросить оплатить картой"],"notes":["How much is this …? спрашивает цену одного предмета.","Pay by card — платить картой; pay in cash — платить наличными."],"lexicon":[{"en":"price","ru":"цена"},{"en":"cash","ru":"наличные"},{"en":"card","ru":"карта"},{"en":"change","ru":"сдача"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"83d1